UPDATE assignments SET lesson = '{"steps": [{"id": "step-1", "body": "1. Go to https://chatgpt.com.\n2. Create a free account.", "title": "Step 1: Open ChatGPT"}, {"id": "step-2", "body": "1. Once signed in, select **New Chat**.\n2. Copy and paste the prompt below and click **Enter** to generate.\n\n> (I want to design an AI-powered mobile app for a school project.\n>\n> Please generate three different app ideas.\n>\n> For each idea include:\n>\n> - App name\n> - Problem it solves\n> - Who would use it\n> - How AI helps users\n> - Three main features\n> - Why people would find it useful\n>\n> Keep the explanations simple enough for a high school student.)\n\n3. Repeat this step two more times for a total of three ChatGPT generated ideas.", "title": "Step 2: Start a New Chat"}, {"id": "step-3", "body": "Carefully read all three ideas and consider the following:\n\n- Which idea sounds the most interesting?\n- Which idea would be fun to build?\n- Which idea could help real people?\n- Which idea has features you understand?", "title": "Step 3: Review the Ideas"}, {"id": "step-4", "body": "1. Open a Word document and create the following headings:\n   - Option 1\n   - Option 2\n   - Option 3\n2. Copy and paste your top 3 ideas. Save the document as: **Week2_AppIdea**\n\n> Remember: There is no \"correct\" answer. Choose the idea you are most excited to continue developing.", "title": "Step 4: Save Initial Ideas"}, {"id": "step-5", "body": "1. Copy and paste the following prompt into ChatGPT.\n\n> (Please compare these three app ideas. Tell me:\n>\n> - The strengths of each idea\n> - The weaknesses of each idea\n> - Which idea would be easiest for a beginner to build\n> - Which idea has the most potential for future improvements\n>\n> Explain your reasoning in simple language.)\n\n2. Read ChatGPT's comparison. Screenshot the comparison and upload it below.", "title": "Step 5: Ask ChatGPT to Compare the Ideas", "evidence": {"title": "Upload Screenshot", "maxFiles": 5, "optional": true, "required": false, "maxSizeMb": 50, "allowLinks": true, "acceptedFiles": ["png", "jpg", "jpeg", "pdf", "docx", "pptx", "zip"], "reflectionPrompt": "Add a short note about what this file shows."}}, {"id": "step-6", "body": "In the same **Week2_AppIdea** document, create the following headings:\n\n- My Final App Idea\n- App Name\n- Problem My App Solves\n- Who Will Use My App\n- Why I Chose This Idea\n\nWrite 2\u20133 sentences for each section and save. Upload a screenshot or PDF of the completed document below.", "title": "Step 6: Choose Your Final App Idea", "evidence": {"title": "Upload Screenshot", "maxFiles": 5, "optional": false, "required": true, "maxSizeMb": 50, "allowLinks": true, "acceptedFiles": ["png", "jpg", "jpeg", "pdf", "docx", "pptx", "zip"], "reflectionPrompt": "Add a short note about what this file shows."}}, {"id": "step-7", "body": "Next, upload this document to the same GitHub repository you created during Week 1.\n\nIf you need a reminder of how to upload a file:\n\n1. Open your GitHub repository in your web browser.\n2. Click **Add file**.\n3. Select **Upload files**.\n4. Drag your document into the upload area or click **Choose your files** to select it from your computer.\n5. Scroll to the bottom of the page.\n6. In the **Commit changes** section, type a short description such as `Week 2 Assignment App Idea`.\n7. Click **Commit changes** to save the file to your repository.\n\n\n\n\n\n\n\n\n\n### Resources\n\n- [ChatGPT](https://chatgpt.com)\n- [How to upload files to GitHub](https://docs.github.com/en/repositories/working-with-files/managing-files/adding-a-file-to-a-repository)", "title": "Step 7: Upload to GitHub"}], "version": 1, "overview": "Every successful app begins with a strong idea. In this assignment, you will use ChatGPT as a brainstorming partner to help you think creatively.\n\nInstead of choosing the first idea that comes to mind, you will generate three possible AI-powered mobile apps. You will compare each idea and decide which one has the most potential. This app will become your semester-long project and will be improved in every future assignment.", "objective": "Use ChatGPT to generate and evaluate three different AI-powered mobile app ideas before selecting one idea to develop throughout the remainder of the course.\n", "difficulty": "beginner", "estimatedMinutes": 60}'::jsonb WHERE id = 'aa841efa-0f07-4d48-81eb-41a3d7c41ec3';
